#[test]
fn checked_in_manifest_is_the_one_a_host_builds_and_validates() {
    let (_, host) = fixture_host();
    let fixture = checked_in();
    let built = definition(&host, &[RELAY.to_owned()]);
    assert_eq!(fixture["definition"], built, "regenerate the fixture");

    let parsed = cap::parse_definition(&fixture["definition"]).expect("NIP-CAP validator");
    assert_eq!(parsed.profile, Profile::Adapter);
    assert_eq!(parsed.transport, "nostr-cj");
    assert_eq!(parsed.component, SLUG);
    assert_eq!(parsed.idempotency, "request_attempt");
    assert_eq!(
        fixture["definition"]["binding_contract"]["operations"],
        json!(OPERATIONS)
    );

    // The schema references pin the checked-in schema documents, and the
    // shared evaluator accepts both.
    for (field, bytes) in [("input", CALL_SCHEMA), ("output", ANSWER_SCHEMA)] {
        let reference = &fixture["definition"][field];
        assert_eq!(reference["digest"], digest_bytes(bytes));
        assert_eq!(reference["size"], bytes.len());
        assert_eq!(reference["media_type"], "application/schema+json");
    }
    let documents = BTreeMap::from([
        (digest_bytes(CALL_SCHEMA), CALL_SCHEMA.to_vec()),
        (digest_bytes(ANSWER_SCHEMA), ANSWER_SCHEMA.to_vec()),
    ]);
    prepare_closure(&documents).expect("the schemas use supported keywords");
}

/// `openagents.spend-grant.v1`: what a host may ask the phone to pay.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Grant {
    pub v: String,
    pub requires: Vec<String>,
    /// 32-byte ID, lowercase hex.
    pub grant: String,
    /// The phone's device key.
    pub issuer: String,
    /// The host's key: the agent side that asks.
    pub grantee: String,
    pub wallet: WalletRef,
    pub mode: Mode,
    pub unit: String,
    /// Ceiling for one payment, fees included.
    pub per_payment_max: u64,
    /// Rolling window in seconds and its ceiling, fees included.
    pub period: u64,
    pub period_max: u64,
    /// Lifetime ceiling, fees included.
    pub total_max: u64,
    pub fee_max: FeeMax,
    pub rails: Vec<Rail>,
    /// Allowed payees: Lightning node keys (compressed, hex). Empty means
    /// none, unless `any_payee` is set.
    pub payees: Vec<String>,
    /// Any payee may be asked for. Only in `request` mode, where the owner
    /// sees the payee decoded from the invoice and approves each payment.
    pub any_payee: bool,
    pub purposes: Vec<Purpose>,
    /// The grantee's epoch at the phone. Revocation advances it.
    pub epoch: u64,
    pub issued_at: u64,
    pub expires_at: u64,
}

#[tokio::test]
async fn cli_reverse_enrollment_is_approved_by_the_owner() {
    use std::io::{BufRead, BufReader};
    use std::os::unix::fs::OpenOptionsExt;
    let (relay, _relay_task, _) = relay::start().await;
    let temp = tempfile::tempdir().unwrap();
    let state = temp.path().join("access");
    let owner = SecretKey::new(&mut secp256k1::rand::rng());
    let init = stdout(&cli(&state, &["init", "--owner", &pubkey(&owner)]));
    let host = init
        .lines()
        .next()
        .unwrap()
        .strip_prefix("host ")
        .unwrap()
        .to_owned();
    // A throwaway fixture key in a private file, as the CLI requires.
    let key_file = temp.path().join("owner.key");
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(&key_file)
        .unwrap();
    std::io::Write::write_all(&mut file, owner.display_secret().to_string().as_bytes()).unwrap();

    let mut requester = Command::new(env!("CARGO_BIN_EXE_coder-access"))
        .arg("--state")
        .arg(&state)
        .args([
            "--loopback-test",
            "request",
            "--relay",
            &relay,
            "--rights",
            "observe,operate",
        ])
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    // Read on a blocking thread so the in-process relay keeps serving the publish.
    let stdout = requester.stdout.take().unwrap();
    let (enrollment, code, lines) = tokio::task::spawn_blocking(move || {
        let mut lines = BufReader::new(stdout).lines();
        let enrollment = lines.next().unwrap().unwrap();
        let code = lines.next().unwrap().unwrap();
        (enrollment, code, lines)
    })
    .await
    .unwrap();
    let code = code.strip_prefix("code ").unwrap().to_owned();
    assert!(enrollment.starts_with("enrollment "));

    let laptop = SecretKey::new(&mut secp256k1::rand::rng());
    let (relay_arg, state_arg, key_arg, host_arg) =
        (relay.clone(), state.clone(), key_file.clone(), host.clone());
    let device = pubkey(&laptop);
    let approved = tokio::task::spawn_blocking(move || {
        Command::new(env!("CARGO_BIN_EXE_coder-access"))
            .arg("--state")
            .arg(&state_arg)
            .env("CODER_ACCESS_KEY_FILE", &key_arg)
            .args([
                "--loopback-test",
                "approve",
                "--relay",
                &relay_arg,
                "--host",
                &host_arg,
                "--device",
                &device,
                "--code",
                &code,
            ])
            .output()
            .unwrap()
    })
    .await
    .unwrap();
    assert!(
        approved.status.success(),
        "{}",
        String::from_utf8_lossy(&approved.stderr)
    );
    let authorization = serde_json::from_slice(&approved.stdout).unwrap();
    let now = coder_access::unix_time().unwrap();
    let access = Access::from_authorization(authorization, &laptop, &host, now, POLICY).unwrap();
    assert_eq!(access.grant.rights.to_list(), "observe,operate");
    let (status, rest) = tokio::task::spawn_blocking(move || {
        let rest: Vec<_> = lines.map_while(|l| l.ok()).collect();
        (requester.wait().unwrap(), rest)
    })
    .await
    .unwrap();
    assert!(status.success());
    assert!(
        rest.iter().any(|l| l.starts_with("approved device")),
        "{rest:?}"
    );
}

#[test]
fn the_default_grant_asks_only_and_validates() {
    let grant = grant(0);
    grant.validate().unwrap();
    assert_eq!(grant.mode, Mode::Request);
    assert!(grant.any_payee);
    assert_eq!(grant.rails, [Rail::Lightning]);
    let mut wide = grant.clone();
    wide.fee_max.ppm = 1_000_001;
    assert_eq!(wide.validate().unwrap_err().code, Code::Bounds);
    let mut long = grant.clone();
    long.expires_at = long.issued_at + MAX_GRANT_LIFETIME + 1;
    assert_eq!(long.validate().unwrap_err().code, Code::Malformed);
    let mut unsorted = grant.clone();
    unsorted.purposes.reverse();
    assert_eq!(unsorted.validate().unwrap_err().code, Code::Malformed);
    let mut other = grant;
    other.unit = "sat".into();
    assert_eq!(other.validate().unwrap_err().code, Code::Unsupported);
    // Unknown fields refuse.
    let mut json = serde_json::to_value(super::tests::grant(0)).unwrap();
    json["auto_approve_max"] = 1.into();
    assert!(serde_json::from_value::<Grant>(json).is_err());
}

/// Publish host-signed private artifacts, such as enrollment requests.
/// Each carries its own recipient; publication grants nothing.
pub async fn publish(&self, relay: &str, events: &[Event]) -> Result<()> {
    self.policy.validate(relay).map_err(Error::from)?;
    let secret = self.key()?;
    let host = pubkey(&secret);
    for event in events {
        if event.pubkey != host {
            return fail(Code::Forbidden, "only host-signed artifacts are published");
        }
        nostr_transport::artifacts::publish(relay, &secret, event)
            .await
            .map_err(|_| Error::new(Code::Transport, "host artifact was not published"))?;
    }
    Ok(())
}

pub fn host(&self) -> Host {
    Host::new(&self.dir, POLICY)
}

/// The host key: the CJ worker.
#[must_use]
pub fn host(&self) -> &str {
    &self.host
}

fn grant(epoch: u64) -> Grant {
    Grant::request_mode(id(0x10 + epoch as u8), PHONE, HOST, epoch, T0)
